import{_ as t,o as a,c as s,ao as n}from"./chunks/framework.CmbWqRQ2.js";const u=JSON.parse('{"title":"Neural inversion (INR)","description":"","frontmatter":{},"headers":[],"relativePath":"inversion/inr.md","filePath":"inversion/inr.md","lastUpdated":null}'),i={name:"inversion/inr.md"};function o(r,e,h,l,d,p){return a(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="Neural-inversion-INR" tabindex="-1">Neural inversion (INR) <a class="header-anchor" href="#Neural-inversion-INR" aria-label="Permalink to &quot;Neural inversion (INR) {#Neural-inversion-INR}&quot;">​</a></h1><p>An <strong>implicit neural representation</strong> replaces the usual &quot;one unknown per cell&quot; with a small neural network that takes a position and returns the density there:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ρ(x, y, z) = network(x, y, z)</span></span></code></pre></div><p>The unknowns are the network&#39;s weights, not the cells. Run it exactly like Gauss–Newton, with an <code>InvCtrl.INR</code> in place of the <code>InvCtrl.GN</code>:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">run </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Invert3D</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;model.start&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;data.xyz&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;FwdCtrl&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">               &quot;InvCtrl.INR&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;C3.dat&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;model.prior&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><h2 id="Why-this-helps" tabindex="-1">Why this helps <a class="header-anchor" href="#Why-this-helps" aria-label="Permalink to &quot;Why this helps {#Why-this-helps}&quot;">​</a></h2><p>Two things follow from the change of parameterization.</p><p><strong>The model is a continuous function of position.</strong> Real geology often is too — a basin that deepens gradually, an alteration halo that fades out, a weathering profile. A cell-based model has to approximate that with a staircase; a coordinate network represents it directly.</p><p><strong>The regularization is the network, not a penalty term.</strong> There is no smallness or smoothing term here at all. A small network simply <em>cannot</em> produce a speckled model — it does not have the capacity. Instead of tuning weights on a penalty, you choose how much capacity to give it.</p><p>The density is squashed through a <code>tanh</code> into your <code>Density bounds</code>, so bounds are respected by construction rather than by projection.</p><h2 id="The-settings-that-matter" tabindex="-1">The settings that matter <a class="header-anchor" href="#The-settings-that-matter" aria-label="Permalink to &quot;The settings that matter {#The-settings-that-matter}&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Hidden width        : 128</span></span>
<span class="line"><span>Hidden layers       : 3</span></span>
<span class="line"><span>Fourier frequencies : 4</span></span>
<span class="line"><span>Learning rate       : 0.015</span></span>
<span class="line"><span>Frequency annealing : 0.5</span></span>
<span class="line"><span>Maximum number of iterations : 1500</span></span></code></pre></div><p><strong><code>Maximum number of iterations</code> counts training epochs</strong>, so it wants hundreds to thousands, not tens. This is the biggest difference from Gauss–Newton in day-to-day use.</p><p><strong><code>Hidden width</code> and <code>Hidden layers</code></strong> are the capacity, and therefore the regularization. Start around 128 × 3. Too small and the model cannot represent the structure; too large and it starts fitting noise.</p><p><strong><code>Fourier frequencies</code></strong> set how fine a spatial feature the network can express. A plain coordinate network is biased towards smooth functions and struggles with sharp edges; Fourier features of the coordinates fix that. More frequencies means sharper structure is available.</p><p><strong><code>Frequency annealing</code></strong> releases those frequency bands coarse-to-fine over this fraction of the training budget. The network finds the broad shape first and adds detail later, which is both more stable and closer to how you would interpret the data yourself.</p><p><strong><code>Learning rate schedule</code></strong> ramps up over the first 2 % of the budget, then decays by a cosine to <code>Learning rate floor</code> of the peak. This matters more than it sounds: with the schedule on, the same network reaches a better model and tolerates a hotter peak rate.</p><p><strong><code>Seed</code></strong> fixes the network initialisation. Change it and re-run as a sanity check — if the answer moves a lot, you are asking for more detail than the data support.</p><h2 id="Keep-the-padding-out" tabindex="-1">Keep the padding out <a class="header-anchor" href="#Keep-the-padding-out" aria-label="Permalink to &quot;Keep the padding out {#Keep-the-padding-out}&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Invert padding : no</span></span></code></pre></div><p>This is the default for <code>InvCtrl.INR</code> and you should leave it alone.</p><p>Nothing in the INR pays for the <em>volume</em> of a cell — there is no smallness, no depth weighting. The padding cells around your survey are enormous compared to core cells, so if they are free the network discovers it can buy misfit very cheaply by filling them with far-field mass, and the run stalls well short of the target. Holding the padding fixed, the same network reaches the target quickly and correlates better with the truth.</p><h2 id="What-training-looks-like" tabindex="-1">What training looks like <a class="header-anchor" href="#What-training-looks-like" aria-label="Permalink to &quot;What training looks like {#What-training-looks-like}&quot;">​</a></h2><p>Adam is not monotone — the misfit goes down overall but wanders on the way. Two things handle that:</p><ul><li><p>the <strong>best</strong> network seen is always kept, so a late bad epoch cannot cost you the result;</p></li><li><p>if the misfit blows past <code>Divergence factor</code> times the best, training falls back to the best network and halves the learning rate, up to <code>Maximum restarts</code> times.</p></li></ul><p>The gradient chains the analytic data-misfit gradient with an automatic-differentiation pullback of the network only — the sensitivity matrix is never traced by AD, which is what keeps it affordable.</p><h2 id="Strengths-and-limits" tabindex="-1">Strengths and limits <a class="header-anchor" href="#Strengths-and-limits" aria-label="Permalink to &quot;Strengths and limits {#Strengths-and-limits}&quot;">​</a></h2><p><strong>Good at</strong>: smoothly varying structure; sparse or irregular surveys, where there is little data and the smoothness of the representation does the interpolating; getting depth right, because it has no incentive to pile mass just under the stations.</p><p>In <code>examples/demo2</code> — a graded basin under 150 scattered stations — it recovers a −2.89 Mt deficit centred at 54 m against a true −3.05 Mt at 52 m, where Gauss–Newton gives −6.34 Mt at 189 m.</p><p><strong>Less good at</strong>: sharp, blocky contacts, where the smooth representation rounds corners; and it is slower in wall-clock terms, needing hundreds of epochs where Gauss–Newton needs a few iterations. On <code>examples/demo1</code>, a blocky truth under a dense regular grid, Gauss–Newton edges it (correlation 0.66 against 0.63).</p><p>See <a href="./choosing">Choosing between them</a>.</p>`,31)])])}const g=t(i,[["render",o]]);export{u as __pageData,g as default};
